result <- function(s1, s2){
  #Get the sequence into individual strings:
  s1_vec <- unlist(strsplit(s1, ""))[[1]]
  s2_vec <- unlist(strsplit(s2,""))[[1]]
  #Identify all mistakes:
  missmatch <- (s1_vec != s2_vec)
  #Count all mistakes (Hammer string):
  cat(sum(missmatch))
}

s1 <-''

s2 <-''

result(s1, s2)

